(()=>{const form=document.querySelector('#dd-review-form');if(!form)return;const note=document.querySelector('#dd-review-note');form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;const button=form.querySelector('button[type=submit]');button.disabled=true;note.textContent='Submitting your review...';try{const data=Object.fromEntries(new FormData(form));data.rating=Number(data.rating);const response=await fetch('/api/reviews',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok||!result.ok)throw Error(result.error||'Submission unavailable');form.reset();note.textContent='Thank you! Your review has been received and is awaiting approval.';}catch(err){note.textContent=err.message||'Please try again later.';}finally{button.disabled=false;}});const grid=document.querySelector('#dd-approved-reviews');if(grid)fetch('/api/reviews').then(r=>r.ok?r.json():{reviews:[]}).then(data=>{const approvedCards=[];for(const item of data.reviews||[]){const card=document.createElement('article');card.className='testimonial-card';const top=document.createElement('div');top.className='testimonial-top';const mark=document.createElement('span');mark.className='testimonial-mark';mark.setAttribute('aria-hidden','true');mark.textContent='“';const project=document.createElement('span');project.className='testimonial-project';project.textContent=item.business||'Client review';top.append(mark,project);const quote=document.createElement('div');quote.className='testimonial-quote';const content=document.createElement('p');content.textContent=item.review;quote.append(content);const footer=document.createElement('div');footer.className='testimonial-footer';const details=document.createElement('div');const heading=document.createElement('strong');heading.textContent=item.name;const date=document.createElement('span');if(item.created_at){const parsed=new Date(item.created_at.replace(' ','T').replace(/Z?$/,'Z'));if(!Number.isNaN(parsed.getTime()))date.textContent=parsed.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});}details.append(heading,date);const stars=document.createElement('span');stars.className='dd-approved-stars';stars.setAttribute('aria-label',item.rating+' out of 5 stars');stars.textContent='★'.repeat(item.rating)+'☆'.repeat(5-item.rating);footer.append(details,stars);card.append(top,quote,footer);approvedCards.push(card);}grid.prepend(...approvedCards);}).catch(()=>{});})();